 const body = req.url.includes("matching-refs") ? [] : { number: 7, title: "Packed executable", state: "closed", merged: true, mergeable: true, mergeable_state: "clean", head: { ref: "feature", sha: "abc" }, auto_merge: null };
 res.writeHead(200, { "content-type": "application/json" }); res.end(JSON.stringify(body));
});
